#!/usr/bin/env node
/**
 * Sync OPENCODE_GO_LOOP_MODELS, CLINE_PASS_LOOP_MODELS, and pricing from models.dev.
 * Regenerate: pnpm sync:models
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const HEADER =
  '// GENERATED by scripts/sync-model-catalog.mjs from https://models.dev/api.json — do not edit. Regenerate: pnpm sync:models\n'

const DEFAULT_URL = 'https://models.dev/api.json'

const ACTIVE_STATUSES = new Set(['active', 'stable'])

function isIncludedStatus(status) {
  if (status == null) return true
  if (typeof status !== 'string') return true
  return ACTIVE_STATUSES.has(status)
}

function mapCost(cost) {
  if (!cost || cost.input == null || cost.output == null) return null
  const row = { input: cost.input, output: cost.output }
  if (cost.cache_read != null) row.cacheRead = cost.cache_read
  if (cost.cache_write != null) row.cacheWrite = cost.cache_write
  return row
}

function ensureClinePassSlug(key) {
  return key.startsWith('cline-pass/') ? key : `cline-pass/${key}`
}

/** @param {Record<string, unknown>} api */
export function transformModelsDevApi(api) {
  const goSlugs = []
  const clineSlugs = []
  const pricing = {}

  const goProvider = api['opencode-go']
  if (goProvider && typeof goProvider === 'object' && goProvider.models) {
    for (const [id, entry] of Object.entries(goProvider.models)) {
      if (!entry || typeof entry !== 'object') continue
      if (!isIncludedStatus(entry.status)) continue
      const rates = mapCost(entry.cost)
      if (!rates) continue
      const slug = `opencode-go/${id}`
      goSlugs.push(slug)
      pricing[slug] = rates
    }
  }

  const clineProvider = api['cline-pass']
  if (clineProvider && typeof clineProvider === 'object' && clineProvider.models) {
    for (const [key, entry] of Object.entries(clineProvider.models)) {
      if (!entry || typeof entry !== 'object') continue
      if (!isIncludedStatus(entry.status)) continue
      const rates = mapCost(entry.cost)
      if (!rates) continue
      const slug = ensureClinePassSlug(key)
      clineSlugs.push(slug)
      pricing[slug] = rates
    }
  }

  goSlugs.sort((a, b) => a.localeCompare(b, 'en'))
  clineSlugs.sort((a, b) => a.localeCompare(b, 'en'))

  return { goSlugs, clineSlugs, pricing }
}

function formatCatalogTs(goSlugs, clineSlugs) {
  const goList = goSlugs.map((s) => `  '${s}',`).join('\n')
  const clineList = clineSlugs.map((s) => `  '${s}',`).join('\n')
  return (
    HEADER +
    `\nexport const OPENCODE_GO_LOOP_MODELS = [\n${goList}\n] as const\n\n` +
    `export const CLINE_PASS_LOOP_MODELS = [\n${clineList}\n] as const\n`
  )
}

function formatPricingTs(pricing) {
  const keys = Object.keys(pricing).sort((a, b) => a.localeCompare(b, 'en'))
  const lines = keys.map((slug) => {
    const r = pricing[slug]
    const parts = [`input: ${r.input}`, `output: ${r.output}`]
    if (r.cacheRead != null) parts.push(`cacheRead: ${r.cacheRead}`)
    if (r.cacheWrite != null) parts.push(`cacheWrite: ${r.cacheWrite}`)
    return `  '${slug}': { ${parts.join(', ')} },`
  })
  return (
    HEADER +
    `\nexport const GENERATED_MODEL_PRICING: Record<string, { input: number; output: number; cacheRead?: number; cacheWrite?: number }> = {\n` +
    lines.join('\n') +
    '\n}\n'
  )
}

export function buildGeneratedBodies(api) {
  const { goSlugs, clineSlugs, pricing } = transformModelsDevApi(api)
  return {
    catalog: formatCatalogTs(goSlugs, clineSlugs),
    pricingFile: formatPricingTs(pricing),
    goSlugs,
    clineSlugs,
    pricingMap: pricing,
  }
}

export function diffGenerated(committed, regenerated) {
  const issues = []
  if (committed.catalog !== regenerated.catalog) {
    const oldGo = [...committed.catalog.matchAll(/'(opencode-go\/[^']+)'/g)].map((m) => m[1])
    const newGo = regenerated.goSlugs
    const addedGo = newGo.filter((s) => !oldGo.includes(s))
    const removedGo = oldGo.filter((s) => !newGo.includes(s))
    if (addedGo.length) issues.push(`opencode-go added: ${addedGo.join(', ')}`)
    if (removedGo.length) issues.push(`opencode-go removed: ${removedGo.join(', ')}`)

    const oldCp = [...committed.catalog.matchAll(/'(cline-pass\/[^']+)'/g)].map((m) => m[1])
    const newCp = regenerated.clineSlugs
    const addedCp = newCp.filter((s) => !oldCp.includes(s))
    const removedCp = oldCp.filter((s) => !newCp.includes(s))
    if (addedCp.length) issues.push(`cline-pass added: ${addedCp.join(', ')}`)
    if (removedCp.length) issues.push(`cline-pass removed: ${removedCp.join(', ')}`)
    if (!addedGo.length && !removedGo.length && !addedCp.length && !removedCp.length) {
      issues.push('model catalog content differs (non-slug change?)')
    }
  }

  if (committed.pricing !== regenerated.pricingFile) {
    const priceRe = /'([^']+)': \{ input: ([^,]+), output: ([^,}]+)/g
    const oldPrices = new Map()
    for (const m of committed.pricing.matchAll(priceRe)) {
      oldPrices.set(m[1], `${m[2]}/${m[3]}`)
    }
    const changed = []
    for (const [slug, row] of Object.entries(regenerated.pricingMap)) {
      const sig = `${row.input}/${row.output}`
      const prev = oldPrices.get(slug)
      if (prev && prev !== sig) changed.push(`${slug}: ${prev} → ${sig}`)
    }
    if (changed.length) issues.push(`pricing changed: ${changed.join('; ')}`)
    else issues.push('pricing file content differs')
  }

  return issues
}

async function main() {
  const check = process.argv.includes('--check')
  const url = process.env.MODELS_DEV_URL ?? DEFAULT_URL
  const res = await fetch(url)
  if (!res.ok) throw new Error(`fetch ${url}: ${res.status}`)
  const api = await res.json()
  const bodies = buildGeneratedBodies(api)

  const root = join(dirname(fileURLToPath(import.meta.url)), '..')
  const catalogPath = join(root, 'src/loop/modelCatalog.generated.ts')
  const pricingPath = join(root, 'src/usage/modelPricing.generated.ts')

  if (check) {
    const committed = {
      catalog: readFileSync(catalogPath, 'utf8'),
      pricing: readFileSync(pricingPath, 'utf8'),
    }
    const issues = diffGenerated(committed, bodies)
    if (issues.length === 0) {
      console.log('sync-model-catalog: OK')
      return
    }
    console.error('sync-model-catalog: drift detected')
    for (const line of issues) console.error(`  ${line}`)
    process.exit(1)
  }

  writeFileSync(catalogPath, bodies.catalog)
  writeFileSync(pricingPath, bodies.pricingFile)
  console.log(
    `wrote ${bodies.goSlugs.length} opencode-go + ${bodies.clineSlugs.length} cline-pass models`,
  )
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((err) => {
    console.error(err)
    process.exit(1)
  })
}
